function timelineNearBottom(timeline){return timeline.scrollHeight-timeline.scrollTop-timeline.clientHeight<72}
function renderMessage(m){if(!m||state.roomMessages.has(m.id))return;state.roomMessages.set(m.id,m);const timeline=$("#messages"),follow=state.hydratingRoom||timelineNearBottom(timeline),bubble=text("article","",`bubble ${messageRole(m)} message-${m.message_type}`);bubble.dataset.messageId=m.id;bubble.dataset.sequence=m.sequence;const head=text("header",`${m.sender_display_name} · ${new Date(m.created_at).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}`,"message-head"),payload=m.structured_payload||{},body=payload.schema==="sagasmith.room-message/v1"?renderPresentation(payload,m.content):text("div",m.content,"message-body");bubble.append(head,body);const suggestions=renderSuggestions(payload);if(suggestions)bubble.append(suggestions);if(m.audience!=="public")bubble.append(text("small",m.audience==="dm"?"仅 DM 可见":"私密消息","audience-badge"));if(m.status==="processing")bubble.append(text("small","SagaSmith 正在结算…","message-status"));if(m.status==="failed")bubble.append(text("small","行动未完成，可重新发送","error"));if(m.structured_payload?.panel_action)bubble.append(text("small",m.structured_payload.panel_action,"receipt-badge"));const next=[...timeline.children].find(x=>Number(x.dataset.sequence)>Number(m.sequence));timeline.insertBefore(bubble,next||null);if(follow){timeline.scrollTop=timeline.scrollHeight;$("#new-messages").hidden=true}else $("#new-messages").hidden=false}
