function renderPlayPanel(){const root=$("#play-panel"),scene=state.panel?.current_module?.scene||state.panel?.current_module||{},party=state.panel?.party||{},dm=["owner","dm"].includes(state.membership?.role);root.replaceChildren(text("p",scene.title||scene.name||"当前没有激活场景","panel-title"));if(scene.summary||scene.description)root.append(text("p",scene.summary||scene.description,"muted"));const clock=state.panel?.campaign?.state?.game_time||party.game_time;if(clock)root.append(text("p",`时间：${clock.label||`${clock.day||0}日 ${clock.hour||0}:${String(clock.minute||0).padStart(2,"0")}`}`,"meta"));const controls=text("div","","panel-actions");controls.append(button("描述行动",()=>{const intent=prompt("你想在当前场景做什么？");if(intent)sendPanelAction("play.intent",{...actionContextPayload(),intent})}),button("掷骰/检定",()=>{const intent=prompt("描述要进行的骰点或检定");if(intent)sendPanelAction("play.intent",{...actionContextPayload(),intent})}));if(dm){if(state.panel?.phase==="lobby")controls.append(button("开始跑团",()=>sendPanelAction("phase.set",{phase:"play"}),"primary"));else if(state.panel?.phase==="play")controls.append(button("返回准备阶段",()=>sendPanelAction("phase.set",{phase:"lobby"})))}root.append(controls)}
