async function openArtifact(a){state.artifact=a;state.releases=await api(`/api/community/artifacts/${a.id}/releases`);$("#forge-list").hidden=true;$("#artifact-detail").hidden=false;const summary=$("#artifact-summary");summary.replaceChildren(text("p",`${typeNames[a.artifact_type]} · ${a.system_id}`,"eyebrow"),text("h2",a.title),text("p",a.summary,"muted"),text("p",`作者 ${a.owner_display_name} · ${a.license_code} · 来源 ${a.source_kind}`,"meta"));const actions=text("div","","actions left");actions.append(button("收藏",async()=>{await api(`/api/community/artifacts/${a.id}/favorite`,{method:"PUT"});toast("已收藏")}));if(a.license_code!=="ARR")actions.append(button("Fork",()=>forkArtifact(a)));actions.append(button("举报",()=>reportArtifact(a)));summary.append(actions);const releases=$("#artifact-releases");releases.replaceChildren(text("h3","发布版本"));for(const r of state.releases){const row=text("div","","release-row");row.append(text("span",`${r.version} · ${r.status}`));if(r.status==="published")row.append(buildInstallControl(a,r));releases.append(row)}await loadArtifactPosts()}
