const abilityLabels={str:"力量",dex:"敏捷",con:"体质",int:"智力",wis:"感知",cha:"魅力",strength:"力量",dexterity:"敏捷",constitution:"体质",intelligence:"智力",wisdom:"感知",charisma:"魅力"};
const skillLabels={acrobatics:"杂技",animal_handling:"驯兽",arcana:"奥秘",athletics:"运动",deception:"欺瞒",history:"历史",insight:"洞悉",intimidation:"威吓",investigation:"调查",medicine:"医药",nature:"自然",perception:"察觉",performance:"表演",persuasion:"游说",religion:"宗教",sleight_of_hand:"巧手",stealth:"隐匿",survival:"求生"};
function num(value,fallback="—"){return value===null||value===undefined||value===""?fallback:value}
function signed(value){const n=Number(value);return Number.isFinite(n)?`${n>=0?"+":""}${n}`:num(value)}
function entries(value){return value&&typeof value==="object"&&!Array.isArray(value)?Object.entries(value):[]}
function isDm(){return ["owner","dm"].includes(state.membership?.role)}
function characters(){return asList(state.panel?.characters,"characters","items")}
function actorId(actor){return actor?.id||actor?.character_id||actor?.actor_id||""}
function actorBinding(id){return (state.panel?.actor_bindings||[]).find(x=>x.actor_id===id&&x.user_id===state.user.id&&x.status!=="revoked")}
function canInspect(id){const binding=actorBinding(id);return isDm()||Boolean(binding?.can_view_private)}
function canControl(id){const binding=actorBinding(id);return isDm()||Boolean(binding?.can_control)}
function cardRecord(id){return state.characterCards.get(id)||null}
function characterActor(id=state.inspectedActorId){return cardRecord(id)?.actor||characters().find(x=>actorId(x)===id)||null}
