function cellKey(cell){if(typeof cell==="string")return cell;if(Array.isArray(cell))return`${cell[0]},${cell[1]}`;return`${cell?.x},${cell?.y}`}
function gridMetrics(canvas){const map=battleMap(),bounds=mapBounds(map),rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}const cell=Math.max(8,Math.min(canvas.width/bounds.width,canvas.height/bounds.height)),offsetX=(canvas.width-cell*bounds.width)/2,offsetY=(canvas.height-cell*bounds.height)/2;return{bounds,dpr,cell,offsetX,offsetY}}
function drawCombatGrid(){const canvas=$("#combat-grid");if(!canvas||combatMode()!=="grid")return;const map=battleMap();if(!map)return;const ctx=canvas.getContext("2d"),m=gridMetrics(canvas),blocked=new Set((map.blocked_cells||map.blocked||[]).map(cellKey)),difficult=new Set((map.difficult_terrain||map.difficult_cells||[]).map(cellKey));ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle="#0b0f0d";ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<m.bounds.height;y++)for(let x=0;x<m.bounds.width;x++){const key=`${x},${y}`;if(blocked.has(key)){ctx.fillStyle="#34302e";ctx.fillRect(m.offsetX+x*m.cell,m.offsetY+y*m.cell,m.cell,m.cell)}else if(difficult.has(key)){ctx.fillStyle="#253529";ctx.fillRect(m.offsetX+x*m.cell,m.offsetY+y*m.cell,m.cell,m.cell)}}ctx.strokeStyle="#29302c";ctx.lineWidth=Math.max(1,m.dpr*.5);for(let x=0;x<=m.bounds.width;x++){ctx.beginPath();ctx.moveTo(m.offsetX+x*m.cell,m.offsetY);ctx.lineTo(m.offsetX+x*m.cell,m.offsetY+m.bounds.height*m.cell);ctx.stroke()}for(let y=0;y<=m.bounds.height;y++){ctx.beginPath();ctx.moveTo(m.offsetX,m.offsetY+y*m.cell);ctx.lineTo(m.offsetX+m.bounds.width*m.cell,m.offsetY+y*m.cell);ctx.stroke()}if(state.gridDestination){ctx.fillStyle="#d9ad5b55";ctx.fillRect(m.offsetX+state.gridDestination.x*m.cell,m.offsetY+state.gridDestination.y*m.cell,m.cell,m.cell)}const current=currentCombatantId();for(const item of combatants()){const position=item.position||item.coordinates;if(!position)continue;const id=combatantId(item),cx=m.offsetX+(Number(position.x)+.5)*m.cell,cy=m.offsetY+(Number(position.y)+.5)*m.cell,r=Math.max(6,m.cell*.34),owned=canControl(id),selected=id===state.selectedTargetId;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle=owned?"#658d70":item.disposition==="hostile"?"#98574f":"#65707f";ctx.fill();ctx.lineWidth=selected?4:current===id?3:1;ctx.strokeStyle=selected?"#e37765":current===id?"#d9ad5b":"#d9ddd8";ctx.stroke();ctx.fillStyle="#fff";ctx.font=`600 ${Math.max(8,Math.min(13,m.cell*.24))}px system-ui`;ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillText(combatantName(id).slice(0,2),cx,cy);const record=cardRecord(id)?.actor,hp=record?.derived?.hit_points||record?.sheet?.combat?.hp;if(hp&&Number(hp.max??hp.maximum)>0){const ratio=Math.max(0,Math.min(1,Number((hp.value??hp.current)??0)/Number(hp.max??hp.maximum)));ctx.fillStyle="#321918";ctx.fillRect(cx-r,cy+r+3,r*2,3*m.dpr);ctx.fillStyle="#a85e51";ctx.fillRect(cx-r,cy+r+3,r*2*ratio,3*m.dpr)}}}
function gridCell(event,canvas){const m=gridMetrics(canvas),rect=canvas.getBoundingClientRect(),x=Math.floor(((event.clientX-rect.left)*m.dpr-m.offsetX)/m.cell),y=Math.floor(((event.clientY-rect.top)*m.dpr-m.offsetY)/m.cell);return x>=0&&y>=0&&x<m.bounds.width&&y<m.bounds.height?{x,y}:null}
function combatantAt(cell){return combatants().find(item=>{const position=item.position||item.coordinates;return position&&Number(position.x)===cell?.x&&Number(position.y)===cell?.y})}
function gridPointerMove(event,canvas,tooltip){const cell=gridCell(event,canvas);if(!cell){tooltip.hidden=true;return}const item=combatantAt(cell),map=battleMap(),terrain=(map.blocked_cells||map.blocked||[]).some(x=>cellKey(x)===cellKey(cell))?"不可通行":(map.difficult_terrain||map.difficult_cells||[]).some(x=>cellKey(x)===cellKey(cell))?"困难地形":"普通地形";tooltip.replaceChildren(text("strong",item?combatantName(combatantId(item)):`坐标 ${cell.x}, ${cell.y}`));if(item){const id=combatantId(item),actor=cardRecord(id)?.actor,hp=actor?.derived?.hit_points||actor?.sheet?.combat?.hp;appendDetails(tooltip,[["先攻",item.initiative],["位置",`${cell.x}, ${cell.y}`],["HP",hp?`${num(hp.value??hp.current)}/${num(hp.max??hp.maximum)}`:undefined],["AC",actor?.derived?.armor_class],["状态",(item.conditions||[]).map(x=>typeof x==="string"?x:x.name||x.id).join("、")],["回合预算",item.turn_budget?JSON.stringify(item.turn_budget):undefined]])}else tooltip.append(text("p",terrain,"small muted"));const wrap=canvas.parentElement,rect=wrap.getBoundingClientRect();tooltip.style.left=`${Math.min(event.clientX-rect.left+12,rect.width-250)}px`;tooltip.style.top=`${Math.min(event.clientY-rect.top+12,rect.height-140)}px`;tooltip.hidden=false}
async function gridClick(event,canvas){const cell=gridCell(event,canvas);if(!cell)return;const item=combatantAt(cell);if(item){await focusCombatant(combatantId(item));return}if(state.actingActorId){state.gridDestination=cell;state.selectedTargetId=null;renderActionContext();drawCombatGrid()}}
window.addEventListener("resize",()=>requestAnimationFrame(drawCombatGrid));

const moduleSteps=["idea","outline_ready","generating","draft_review","ready_to_finalize","compiled"];
const moduleLabels={idea:"创意",outlining:"提纲生成中",outline_ready:"提纲已就绪",generating:"正文生成中",draft_review:"审校",ready_to_finalize:"可定稿",finalizing:"编译中",compiled:"已编译",failed:"失败",canceled:"已取消"};
async function loadModules(){state.modules=await api("/api/modules");const root=$("#module-list");root.hidden=false;$("#module-detail").hidden=true;root.replaceChildren();for(const m of state.modules){const card=text("article","","card module-card");card.append(text("p",`${moduleLabels[m.status]||m.status} · D&D ${m.edition}`,"eyebrow"),text("h3",m.title),text("p",m.brief,"muted"),text("p",`${m.version} · ${m.used_tokens.toLocaleString()} tokens`,"meta"),button("继续创作",()=>openModule(m),"primary"));root.append(card)}}
$("#new-module").onclick=()=>$("#module-form").hidden=false;$("#cancel-module").onclick=()=>$("#module-form").hidden=true;
$("#module-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body=Object.fromEntries(f);for(const key of ["starting_level","ending_level","party_size","session_hours"])body[key]=Number(body[key]);body.locale="zh-CN";try{const created=await api("/api/modules",{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify(body)});e.target.reset();e.target.hidden=true;await openModule(created)}catch(err){toast(err.message)}};
async function openModule(m){state.module=await api(`/api/modules/${m.id}`);$("#module-list").hidden=true;$("#module-form").hidden=true;$("#module-detail").hidden=false;await renderModule();watchModule()}
$("#close-module").onclick=()=>{if(state.moduleEvents)state.moduleEvents.close();state.module=null;loadModules()};
function watchModule(){if(state.moduleEvents)state.moduleEvents.close();state.moduleEvents=new EventSource(`/api/modules/${state.module.id}/events`);state.moduleEvents.addEventListener("module",e=>{const data=JSON.parse(e.data);state.module=data.project;renderModule(data.run).catch(()=>{})});state.moduleEvents.onerror=()=>{state.moduleEvents?.close();state.moduleEvents=null}};
async function renderModule(latestRun=null){const m=state.module;$("#module-state").textContent=`${moduleLabels[m.status]||m.status} · D&D ${m.edition}`;$("#module-title").textContent=m.title;$("#module-brief").textContent=m.brief;$("#module-budget").textContent=`${m.used_tokens.toLocaleString()} / ${m.budget_tokens.toLocaleString()} tokens`;const timeline=$("#module-timeline");timeline.replaceChildren(...moduleSteps.map(step=>{const el=text("span",moduleLabels[step],"timeline-step");const current=moduleSteps.indexOf(m.status),target=moduleSteps.indexOf(step);if(target>=0&&current>=target)el.classList.add("done");if(step===m.status)el.classList.add("current");return el}));$("#module-outline").textContent=Object.keys(m.outline||{}).length?JSON.stringify(m.outline,null,2):"等待生成提纲";const review=$("#module-review");review.replaceChildren();if(m.review?.summary){review.append(text("p",`${m.review.approved?"通过":"需修订"} · ${m.review.summary}`,m.review.approved?"success":"error"));for(const finding of m.review.findings||[])review.append(text("p",`${finding.severity||"info"}: ${finding.message||""}`,"muted"))}await Promise.all([renderModuleSources(),renderModuleRuns(latestRun)]);renderModuleActions();renderInstallPublish()}
async function renderModuleSources(){const items=await api(`/api/modules/${state.module.id}/sources`),root=$("#module-sources");root.replaceChildren();for(const item of items)root.append(text("p",`v${item.generation} · ${item.name} · ${item.rights_basis}`,"small muted"));const latest=items[0],kind=$("#module-publish-form select[name=source_kind]"),provenance=$("#module-publish-form textarea[name=provenance]");if(latest&&kind){kind.value=latest.rights_basis==="open_licensed"?"open_licensed":"original";if(provenance&&!provenance.value)provenance.value=latest.attribution||"原创内容，由账号持有人确认发布权利。"}}
async function renderModuleRuns(latestRun){state.moduleRuns=await api(`/api/modules/${state.module.id}/runs`);const root=$("#module-runs");root.replaceChildren();for(const run of state.moduleRuns){const row=text("div","","review-row");row.append(text("span",`${run.run_type} · ${run.status} · ${run.prompt_tokens+run.completion_tokens} tokens`));if(["queued","running"].includes(run.status))row.append(button("取消",()=>cancelModuleRun(run)));if(["failed","canceled"].includes(run.status))row.append(button("重试",()=>retryModuleRun(run)));if(run.error)row.append(text("small",run.error,"error"));root.append(row)}if(latestRun&&["succeeded","failed","canceled"].includes(latestRun.status))toast(latestRun.status==="succeeded"?"模组任务已完成":latestRun.error||"模组任务未完成")}
function renderModuleActions(){const root=$("#module-actions"),m=state.module,active=state.moduleRuns.some(r=>["queued","running"].includes(r.status));root.replaceChildren();if(active){root.append(text("span","任务正在后台执行，可离开此页面","muted"));return}const add=(label,action,klass="")=>root.append(button(label,()=>queueModuleAction(action),klass));if(["idea","failed","canceled"].includes(m.status))add("生成提纲","outline","primary");if(m.status==="outline_ready"&&!m.specification.outline_approved){root.append(button("批准提纲",()=>decideOutline(true),"primary"),button("退回修改",()=>decideOutline(false)))}if(m.status==="outline_ready"&&m.specification.outline_approved)add("生成完整模组","generate","primary");if(m.status==="draft_review")add("Agent 证据审校","review","primary");if(["draft_review","ready_to_finalize"].includes(m.status))add("按意见修订","revise");if(m.status==="ready_to_finalize")add("确认并编译","finalize","primary");if(m.status==="compiled")root.append(button("创建新版本",createModuleVersion))}
async function queueModuleAction(action){const instruction=$("#module-instruction").value;let body={instruction};if(action==="finalize")body={confirmed:true,note:instruction||"作者确认该版本已完成 Agent 证据审校，可以编译。",version:state.module.version};try{await api(`/api/modules/${state.module.id}/${action}`,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify(body)});state.module=await api(`/api/modules/${state.module.id}`);await renderModule();watchModule()}catch(err){toast(err.message)}}
async function createModuleVersion(){const version=prompt("新版本号",state.module.version);if(!version||version===state.module.version)return;try{await api(`/api/modules/${state.module.id}/revise`,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({instruction:$("#module-instruction").value||"Create the next release from the compiled module.",version})});renderModule();watchModule()}catch(err){toast(err.message)}}
async function decideOutline(approved){try{state.module=await api(`/api/modules/${state.module.id}/outline-decision`,{method:"POST",body:JSON.stringify({approved,feedback:$("#module-instruction").value})});await renderModule()}catch(err){toast(err.message)}}
async function cancelModuleRun(run){await api(`/api/modules/${state.module.id}/runs/${run.id}/cancel`,{method:"POST"});state.module=await api(`/api/modules/${state.module.id}`);renderModule()}
async function retryModuleRun(run){await api(`/api/modules/${state.module.id}/runs/${run.id}/retry`,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()}});renderModule();watchModule()}
$("#module-source-form").onsubmit=async e=>{e.preventDefault();try{await api(`/api/modules/${state.module.id}/sources`,{method:"POST",body:new FormData(e.target)});e.target.reset();state.module=await api(`/api/modules/${state.module.id}`);await renderModule();toast("来源资料已安全保存")}catch(err){toast(err.message)}};
function renderInstallPublish(){const compiled=state.module.status==="compiled";$("#module-install-form").hidden=!compiled;$("#module-publish-form").hidden=!compiled||!!state.module.published_release_id;const select=$("#module-install-form select");select.replaceChildren(...state.campaigns.map(c=>{const o=text("option",c.name);o.value=c.id;return o}))}
$("#module-install-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api(`/api/modules/${state.module.id}/install`,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({campaign_id:f.get("campaign_id"),activate:f.has("activate")})});renderModule();watchModule();toast("安装任务已提交")}catch(err){toast(err.message)}};
$("#module-publish-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api(`/api/modules/${state.module.id}/publish`,{method:"POST",body:JSON.stringify({visibility:"public",license_code:f.get("license_code"),rights_attested:f.has("rights_attested"),source_kind:f.get("source_kind"),provenance:{author_statement:f.get("provenance")},summary:f.get("summary"),tags:["dnd5e","module"],changelog:"Module Studio release"})});state.module=await api(`/api/modules/${state.module.id}`);renderModule();toast("已提交平台审核")}catch(err){toast(err.message)}};

setInterval(()=>{if(state.campaign&&!$("#campaign-room").hidden)refreshRuntime().catch(()=>{})},5000);
boot();
